from inspect import signature

import torch
from torch.nn import Module
from torch import cat, is_tensor
from torch.utils._pytree import tree_map, tree_flatten
from einops import repeat, reduce, rearrange

# explorative modeling (forward xm)
# Alexi Gladstone et al. https://arxiv.org/abs/2607.27372

# helpers

def exists(v):
    return v is not None

def default(v, d):
    return v if exists(v) else d

def is_batch_tensor(t, b):
    if not is_tensor(t) or t.ndim == 0:
        return False

    batch = t.shape[0]
    return batch == b

# xm wrapper

class XMWrapper(Module):
    def __init__(
        self,
        flow_model: Module,
        candidates = 1,
        max_batch_size = None,
        random_time_method = 'random_times',
        random_time_kwarg = 'times'
    ):
        super().__init__()
        self.flow_model = flow_model

        assert candidates >= 1, 'candidates must be at least 1'
        self.candidates = candidates
        self.max_batch_size = max_batch_size
        self.has_loss_reduction = 'loss_reduction' in signature(flow_model.forward).parameters

        self.random_time_method = random_time_method
        self.random_time_kwarg = random_time_kwarg

    @property
    def data_shape(self):
        return getattr(self.flow_model, 'data_shape', None)

    @data_shape.setter
    def data_shape(self, val):
        if hasattr(self.flow_model, 'data_shape'):
            self.flow_model.data_shape = val

    def sample(self, *args, **kwargs):
        return self.flow_model.sample(*args, **kwargs)

    def forward(
        self,
        *args,
        candidates = None,
        max_batch_size = None,
        **kwargs
    ):
        candidates = default(candidates, self.candidates)
        max_batch_size = default(max_batch_size, self.max_batch_size)

        if candidates == 1:
            return self.flow_model(*args, **kwargs)

        # find batch size from first tensor in inputs

        leaves, _ = tree_flatten((args, kwargs))
        first_tensor = next(t for t in leaves if is_tensor(t))
        batch = first_tensor.shape[0]

        # sample anything that must be shared before expanding candidates

        if hasattr(self.flow_model, 'xm_shared_random_kwargs'):
            random_kwargs = self.flow_model.xm_shared_random_kwargs(batch)

            for key, value in random_kwargs.items():
                if not exists(kwargs.get(key)):
                    kwargs[key] = value

        if not exists(kwargs.get(self.random_time_kwarg)):
            assert hasattr(self.flow_model, self.random_time_method), f'flow_model must have a {self.random_time_method} method'
            fn = getattr(self.flow_model, self.random_time_method)
            kwargs[self.random_time_kwarg] = fn(batch)

        # repeat inputs K candidates times

        args_K, kwargs_K = tree_map(
            lambda t: repeat(t, 'b ... -> (b k) ...', k = candidates) if is_batch_tensor(t, batch) else t,
            (args, kwargs)
        )

        total = batch * candidates
        chunk_size = default(max_batch_size, total) if self.has_loss_reduction else 1
        extra_kwargs = {'loss_reduction': 'none'} if self.has_loss_reduction else dict()

        # forward passes

        losses = []

        for start in range(0, total, chunk_size):
            end = min(start + chunk_size, total)

            chunk_args, chunk_kwargs = tree_map(
                lambda t: t[start:end] if is_batch_tensor(t, total) else t,
                (args_K, kwargs_K)
            )
            chunk_kwargs.update(extra_kwargs)

            loss = self.flow_model(*chunk_args, **chunk_kwargs)
            loss = rearrange(loss, '-> 1 1') if loss.ndim == 0 else rearrange(loss, 'b ... -> b (...)')
            losses.append(loss)

        # select candidate with minimum loss for each sample in batch

        raw_loss = cat(losses, dim = 0)
        candidate_losses = reduce(raw_loss, '(b k) ... -> b k', 'mean', b = batch, k = candidates)

        return candidate_losses.amin(dim = -1).mean()

import copy
import importlib

import pytest
import torch
from torch import nn

from denoising_diffusion_pytorch import classifier_free_guidance as cfg
from denoising_diffusion_pytorch.xm import XMWrapper

MODULES = [
    "denoising_diffusion_pytorch",
    "denoising_diffusion_pytorch_1d",
    "continuous_time_gaussian_diffusion",
    "v_param_continuous_time_gaussian_diffusion",
]


class Denoiser(nn.Module):
    channels = out_dim = 1
    self_condition = False

    def __init__(self, sequence, continuous):
        super().__init__()
        self.random_or_learned_sinusoidal_cond = continuous
        self.conv = nn.Conv1d(1, 1, 1) if sequence else nn.Conv2d(1, 1, 1)
        self.seen_times = []

    def forward(self, x, times, *args, **kwargs):
        self.seen_times.append(times.detach().clone())
        return self.conv(x)


def compare_loss_and_gradients(
    actual, expected, images, actual_kwargs, expected_kwargs, chunk
):
    torch.manual_seed(7)
    result = XMWrapper(actual, candidates=3, max_batch_size=chunk)(
        images, **actual_kwargs
    )
    result.backward()
    torch.manual_seed(7)
    reference = XMWrapper(expected, candidates=3, max_batch_size=chunk)(
        images, **expected_kwargs
    )
    reference.backward()
    torch.testing.assert_close(result, reference, rtol=0, atol=0)
    for actual_parameter, expected_parameter in zip(
        actual.parameters(), expected.parameters()
    ):
        if expected_parameter.grad is None:
            assert actual_parameter.grad is None
        else:
            torch.testing.assert_close(
                actual_parameter.grad, expected_parameter.grad, rtol=0, atol=0
            )


@pytest.mark.parametrize("module_name", MODULES)
@pytest.mark.parametrize("chunk", [2, 6])
@pytest.mark.parametrize("provided", [False, True])
def test_none_times_matches_omitted_shared_times(module_name, chunk, provided):
    module = importlib.import_module(f"denoising_diffusion_pytorch.{module_name}")
    sequence = module_name.endswith("_1d")
    continuous = "continuous_time" in module_name
    torch.manual_seed(31)
    model = Denoiser(sequence, continuous)
    if sequence:
        diffusion = module.GaussianDiffusion1D(model, seq_length=4, timesteps=8)
        images = torch.linspace(0.1, 0.9, 8).reshape(2, 1, 4)
    elif continuous:
        diffusion_type = (
            module.VParamContinuousTimeGaussianDiffusion
            if module_name.startswith("v_param")
            else module.ContinuousTimeGaussianDiffusion
        )
        diffusion = diffusion_type(model, image_size=4, channels=1)
        images = torch.linspace(0.1, 0.9, 32).reshape(2, 1, 4, 4)
    else:
        diffusion = module.GaussianDiffusion(
            model, image_size=4, timesteps=8, beta_schedule="cosine"
        )
        images = torch.linspace(0.1, 0.9, 32).reshape(2, 1, 4, 4)
    reference = copy.deepcopy(diffusion)
    times = torch.tensor([0.2, 0.7]) if continuous else torch.tensor([1, 5])
    kwargs = {"times": times if provided else None}
    reference_kwargs = {"times": times} if provided else {}
    compare_loss_and_gradients(
        diffusion, reference, images, kwargs, reference_kwargs, chunk
    )
    observed = torch.cat(model.seen_times).reshape(2, 3)
    torch.testing.assert_close(
        observed, observed[:, :1].expand_as(observed), rtol=0, atol=0
    )
    if not provided:
        assert kwargs["times"] is None
    else:
        assert kwargs["times"] is times


@pytest.mark.parametrize("chunk", [2, 6])
@pytest.mark.parametrize("setting", ["times", "cond_keep_mask", "both", "provided"])
def test_none_cfg_shared_inputs_match_omitted_defaults(chunk, setting):
    torch.manual_seed(31)
    model = cfg.Unet(
        dim=8, dim_mults=(1,), channels=1, num_classes=2, cond_drop_prob=0.5
    )
    diffusion = cfg.GaussianDiffusion(
        model, image_size=4, timesteps=8, beta_schedule="cosine"
    )
    reference = copy.deepcopy(diffusion)
    images = torch.linspace(0.1, 0.9, 32).reshape(2, 1, 4, 4)
    classes = torch.tensor([0, 1])
    kwargs = {"classes": classes}
    reference_kwargs = {"classes": classes}
    if setting == "provided":
        kwargs.update(
            times=torch.tensor([1, 5]), cond_keep_mask=torch.tensor([True, False])
        )
        reference_kwargs.update(kwargs)
    else:
        if setting in ("times", "both"):
            kwargs["times"] = None
        if setting in ("cond_keep_mask", "both"):
            kwargs["cond_keep_mask"] = None
    observed = []

    def record_inputs(module, args, keyword_args):
        mask = keyword_args.get("cond_keep_mask")
        observed.append((args[1].clone(), None if mask is None else mask.clone()))

    handle = model.register_forward_pre_hook(record_inputs, with_kwargs=True)
    compare_loss_and_gradients(
        diffusion, reference, images, kwargs, reference_kwargs, chunk
    )
    handle.remove()
    times = torch.cat([row[0] for row in observed]).reshape(2, 3)
    torch.testing.assert_close(times, times[:, :1].expand_as(times), rtol=0, atol=0)
    assert all(row[1] is not None for row in observed)
    masks = torch.cat([row[1] for row in observed]).reshape(2, 3)
    assert torch.equal(masks, masks[:, :1].expand_as(masks))
    if setting == "provided":
        assert torch.equal(times[:, 0], kwargs["times"])
        assert torch.equal(masks[:, 0], kwargs["cond_keep_mask"])

import importlib

import pytest
import torch
from accelerate.data_loader import prepare_data_loader
from torch import nn
from torch.utils.data import DataLoader, Dataset


class ImageSamples(Dataset):
    def __init__(self, *args, **kwargs):
        pass

    def __len__(self):
        return 128

    def __getitem__(self, index):
        return torch.full((1, 4, 4), index / 127)


class ConvolutionalDenoiser(nn.Module):
    channels = out_dim = 1
    self_condition = random_or_learned_sinusoidal_cond = False

    def __init__(self, sequence):
        super().__init__()
        self.conv = (nn.Conv1d if sequence else nn.Conv2d)(1, 1, 1)

    def forward(self, x, time, self_condition=None):
        return self.conv(x)


@pytest.mark.parametrize("split", [None, False, True])
@pytest.mark.parametrize(
    "name",
    [
        "denoising_diffusion_pytorch",
        "denoising_diffusion_pytorch_1d",
        "guided_diffusion",
        "repaint",
    ],
)
def test_trainer_configuration_controls_actual_batch_shards(
    monkeypatch, tmp_path, name, split
):
    module = importlib.import_module(f"denoising_diffusion_pytorch.{name}")
    monkeypatch.setattr(module, "cpu_count", lambda: 0)
    sequence = name.endswith("_1d")
    model = ConvolutionalDenoiser(sequence)
    if sequence:
        diffusion = module.GaussianDiffusion1D(model, seq_length=8, timesteps=4)
        dataset = module.Dataset1D(
            torch.arange(128).float().reshape(128, 1, 1).expand(-1, -1, 8) / 127
        )
        trainer_class, data = module.Trainer1D, dataset
    else:
        monkeypatch.setattr(module, "Dataset", ImageSamples)
        dataset = ImageSamples()
        diffusion = module.GaussianDiffusion(
            model, image_size=4, timesteps=4, beta_schedule="cosine"
        )
        trainer_class, data = module.Trainer, str(tmp_path)
    extra = (
        {"calculate_fid": False}
        if name in ("denoising_diffusion_pytorch", "repaint")
        else {}
    )
    if split is not None:
        extra["split_batches"] = split
    trainer = trainer_class(
        diffusion,
        data,
        train_batch_size=16,
        train_num_steps=1,
        num_samples=4,
        save_and_sample_every=1000,
        results_folder=str(tmp_path),
        **extra,
    )
    # Exercise Accelerate's real sharding implementation without requiring sockets.
    shards = [
        prepare_data_loader(
            DataLoader(dataset, batch_size=16),
            num_processes=2,
            process_index=rank,
            split_batches=trainer.accelerator.split_batches,
            rng_types=[],
        )
        for rank in range(2)
    ]
    batches = [next(iter(shard)) for shard in shards]
    before = [p.detach().clone() for p in model.parameters()]
    trainer.dl = module.cycle(shards[0])
    trainer.train()
    assert trainer.step == 1
    assert all(torch.isfinite(p).all() for p in model.parameters())
    assert any(
        not torch.equal(old, new) for old, new in zip(before, model.parameters())
    )
    expected_local = 16 if split is False else 8
    assert [len(batch) for batch in batches] == [expected_local, expected_local]
    ids = torch.cat(batches).flatten(1)[:, 0] * 127
    assert ids.round().int().tolist() == list(range(expected_local * 2))

